.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1b (his #50, from the AAA judge of the Wirt and Last Pour shots): A WINDOW SITS IN A DARK ROOM. The room
   behind a window was dimmed to 82 percent, so round a card window (Wirt, the Last Pour, the Terms, the party) the big station
   signs of the Undercroft still read as cut off words, SHOP, CR and POUR and MAY GLITCH, like a second menu under the first.
   The room is dimmed to 93 percent now: the floor is still there, a shape and no words. */
#root .modal{ background:radial-gradient(1200px 600px at 50% -10%, rgba(170,164,152,.05), transparent 60%), rgba(6,7,8,.93); }

ctx.font=FS(TYPE.micro); ctx.fillStyle='#aeb8c2';
// vNN.xx (ui5q1b, his #50, the Wirt shot): the money line is the floor's, like its heading (v20.88): not painted while a window is open
if(!hubWinOn()) ctx.fillText('$'+P.credits.toLocaleString()

check:
{v:'VER',what:'his #50 (UI redesign ui5q1b, from the AAA judge of the Wirt and Last Pour shots): the room behind a window is dimmed to at least 90 percent, and the floor money line is not painted while a window is open (and still is with none open)',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   if(typeof drawHubHUD!=='function'||typeof hubWinOn!=='function') return 'SKIP: no floor HUD here';
   var bad=[], m, c, a, seen, own, need='in st'+'ash';
   function draws(){ var out=[], real=CanvasRenderingContext2D.prototype.fillText; ctx.fillText=function(t){ out.push(String(t)); return real.apply(this,arguments); };
     try{ drawHubHUD(0,0); }finally{ delete ctx.fillText; } return out.join('|'); }
   try{
     __topClear(); __hubEnter();
     seen=draws();
     if(seen.indexOf(need)<0) bad.push('control: with no window open the floor money line was not painted ('+seen.slice(0,80)+')');
     __station('gamble','KeyE');
     m=document.getElementById('gamblemodal');
     if(!m||!m.classList.contains('on')) return 'SKIP: Wirt did not open';
     c=getComputedStyle(m).backgroundColor; a=/rgba\(/.test(c)?parseFloat(c.split(',')[3]):1;
     if(!(a>=0.9)) bad.push('the room behind a window is dimmed only to '+a+' ('+c+')');
     seen=draws();
     if(seen.indexOf(need)>=0) bad.push('the floor money line is painted behind Wirt');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ delete ctx.fillText; }catch(_d){} try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
